IF SCHEMA_ID(N'api') IS NULL EXEC(N'CREATE SCHEMA api');
GO
CREATE TABLE api.OrchestratorRoute(OrchestratorRouteId BIGINT IDENTITY PRIMARY KEY,IntentCode VARCHAR(60) NOT NULL UNIQUE,DomainCode VARCHAR(30) NOT NULL,AgentCode VARCHAR(30) NULL,WorkflowCode VARCHAR(60) NULL,RequiredPermission VARCHAR(100) NOT NULL,ExecutionMode VARCHAR(20) NOT NULL DEFAULT('READ_ONLY'),Priority INT NOT NULL DEFAULT(100),IsActive BIT NOT NULL DEFAULT(1),CHECK(ExecutionMode IN('READ_ONLY','ANALYZE','RECOMMEND','PREPARE','CONTROLLED_ACTION')),CHECK(AgentCode IS NOT NULL OR WorkflowCode IS NOT NULL));
CREATE TABLE api.OrchestratorRequest(OrchestratorRequestId BIGINT IDENTITY PRIMARY KEY,RequestId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() UNIQUE,UserId BIGINT NOT NULL,CompanyId BIGINT NOT NULL,TransactionId BIGINT NULL,ConversationId VARCHAR(100) NULL,Message NVARCHAR(8000) NOT NULL,DetectedIntent VARCHAR(60) NULL,RouteId BIGINT NULL,Status VARCHAR(25) NOT NULL DEFAULT('RECEIVED'),CreatedAt DATETIME2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2(3) NULL,FOREIGN KEY(UserId) REFERENCES core.AppUser(UserId),FOREIGN KEY(CompanyId) REFERENCES core.Company(CompanyId),FOREIGN KEY(TransactionId) REFERENCES core.BusinessTransaction(TransactionId),FOREIGN KEY(RouteId) REFERENCES api.OrchestratorRoute(OrchestratorRouteId));
GO
